import "dart:convert"; import "package:dio/dio.dart"; import "package:flutter_secure_storage/flutter_secure_storage.dart"; import "package:flutter/material.dart"; import "../config/api_config.dart"; class HttpClient { static final HttpClient _instance = HttpClient._internal(); factory HttpClient() => _instance; HttpClient._internal(); late Dio _dio; final FlutterSecureStorage _secureStorage = const FlutterSecureStorage(); void initialize() { _dio = Dio(BaseOptions(baseUrl: ApiConfig.baseUrl, connectTimeout: const Duration(seconds: 30), receiveTimeout: const Duration(seconds: 30), headers: {"Content-Type": "application/json", "Accept": "application/json"})); _dio.interceptors.add(_AuthInterceptor(_secureStorage)); _dio.interceptors.add(_ErrorInterceptor()); } Dio get dio => _dio; Future<String?> getToken() async { return await _secureStorage.read(key: "auth_token"); } Future<void> setToken(String token) async { await _secureStorage.write(key: "auth_token", value: token); } Future<void> removeToken() async { await _secureStorage.delete(key: "auth_token"); } } class _AuthInterceptor extends Interceptor { final FlutterSecureStorage _secureStorage; _AuthInterceptor(this._secureStorage); @override void onRequest(RequestOptions options, RequestInterceptorHandler handler) async { final token = await _secureStorage.read(key: "auth_token"); if (token != null && token.isNotEmpty) { options.headers["Authorization"] = "Bearer \$token"; } handler.next(options); } } class _ErrorInterceptor extends Interceptor { @override void onError(DioException err, ErrorInterceptorHandler handler) { if (err.response?.statusCode == 401) { debugPrint("Unauthorized access detected"); } handler.next(err); } }
